const { chromium } = require("playwright");
const fs = require("fs");
const out = process.argv[2];
const salon = JSON.parse(fs.readFileSync("/home/user/LaunchWitness/backend/tests/fixtures/sellers_hard/salon.json"));
(async () => {
  const b = await chromium.launch();
  const page = await (await b.newContext({ viewport: { width: 390, height: 844 } })).newPage();
  page.on("pageerror", (e) => console.log("PAGE ERROR", e.message));
  await page.goto("http://localhost:8000/#/try");
  const t = page.locator("textarea");
  await t.nth(0).fill(salon.description);
  await t.nth(1).fill(salon.price_list);
  await page.click("button[type=submit]");
  await page.waitForTimeout(1500);
  await page.screenshot({ path: out + "/scope-guard-phone.png" });
  console.log("salon text:", (await page.locator("main").innerText()).slice(0, 600));

  await page.goto("http://localhost:8000/#/try");
  await page.getByRole("button", { name: /Meera/ }).first().click();
  await page.click("button[type=submit]");
  await page.waitForURL(/#\/b\/\d+/, { timeout: 10000 });
  await page.waitForSelector("text=How customers order");
  await page.getByLabel("Phone number").fill("98765 43210");
  await page.getByLabel("WhatsApp number").fill("98765 43210");
  await page.getByLabel("UPI ID").fill("meera.demo@example");
  await page.getByLabel("Name your UPI app shows").fill("MEERA DEMO");
  await page.getByLabel(/What makes you special/).fill("100% eggless");
  await page.getByLabel(/message for the item/).check();
  await page.locator("h2", { hasText: "How customers order" }).scrollIntoViewIfNeeded();
  await page.screenshot({ path: out + "/review-how-customers-order-phone.png" });
  await page.click("button[type=submit]");
  await page.waitForSelector("text=Saved");
  const site = await page.locator("a", { hasText: "View my website" }).getAttribute("href");
  console.log("site", site);
  const s = await b.newPage({ viewport: { width: 390, height: 844 } });
  await s.goto(site.replace("localhost/", "localhost:8000/"));
  console.log("badges:", await s.locator(".badges").innerText());
  console.log("item message field:", await s.locator("#item_message").count());
  await s.click(".item .add");
  await s.fill("#customer_name", "Asha");
  await s.fill("#customer_phone", "99887 76655");
  await s.fill("#item_message", "Happy Birthday Riya");
  await s.click("button[type=submit]");
  await s.waitForSelector("text=Thank you");
  await s.screenshot({ path: out + "/thanks-phone.png", fullPage: true });
  await b.close();
})();

